 "content": "def transform(grid):
    # Recolor each solid rectangular region of a single repeated color 8 or 1
    # that is bounded as part of the noisy field; these are large embedded blocks.
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color not in (1, 8) or (r,c) in seen:
                continue
            stack=[(r,c)]; comp=[]; seen.add((r,c))
            while stack:
                y,x=stack.pop(); comp.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<h and 0<=nx<w and (ny,nx) not in seen and grid[ny][nx]==color:
                        seen.add((ny,nx)); stack.append((ny,nx))
            # solid large rectangular patch -> change to 4
            ys=[p[0] for p in comp]; xs=[p[1] for p in comp]
            y0,y1,x0,x1=min(ys),max(ys),min(xs),max(xs)
            if len(comp)>=20 and len(comp)==(y1-y0+1)*(x1-x0+1):
                for y,x in comp: out[y][x]=4
    return out
